// Generated by Atlas Genesis (web-app template). Renders the dashboard, record
// screens, booking form, sign-in and files described in app.config.json. All
// text is set with textContent, never HTML, so stored data cannot inject markup.

const main = document.getElementById("main");
const nav = document.getElementById("nav");
const toast = document.getElementById("toast");
let config = null;
// Every route change starts a new view. A render that awaited the network
// checks it is still the current view before touching the page, so a slow
// response from the screen the person just left can never replace the one
// they are on.
let view = 0;
const currentView = () => { const mine = view; return () => mine === view; };

function h(tag, attributes = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attributes)) {
    if (value === false || value === null || value === undefined) continue;
    if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
    else if (key === "text") node.textContent = value;
    else node.setAttribute(key, value === true ? "" : String(value));
  }
  for (const child of children.flat()) if (child !== null && child !== undefined && child !== false) node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  return node;
}

async function api(path, options = {}) {
  const response = await fetch(`/api/${path}`, { ...options, headers: { "content-type": "application/json", ...(options.headers ?? {}) } });
  const body = await response.json().catch(() => ({}));
  // Signed out (or the session ended): show the sign-in screen.
  if (response.status === 401 && config?.auth?.required && !path.startsWith("auth/")) {
    renderSignIn(body.signupOpen);
    throw Object.assign(new Error("Sign in to continue."), { errors: {}, signedOut: true });
  }
  if (!response.ok) throw Object.assign(new Error(body.error ?? `Request failed (${response.status}).`), { errors: body.errors ?? {} });
  return body;
}

let user = null;

function renderSignIn(signupOpen) {
  view += 1;
  user = null;
  nav.hidden = true;
  const mode = signupOpen ? "signup" : "login";
  const control = (key, type, autocomplete) => h("div", { class: "field" },
    h("label", { for: `auth-${key}`, text: key === "email" ? "Email" : "Password" }),
    h("input", { id: `auth-${key}`, name: key, type, required: true, autocomplete, minlength: key === "password" ? 8 : null }),
    h("p", { class: "field-error", id: `auth-${key}-error`, hidden: true }));
  const form = h("form", { class: "card form", novalidate: true, "data-prefix": "auth" },
    control("email", "email", "email"),
    control("password", "password", mode === "signup" ? "new-password" : "current-password"),
    h("div", { class: "actions" }, h("button", { type: "submit", text: mode === "signup" ? "Create the owner account" : "Sign in" })));
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const button = form.querySelector("button[type=submit]");
    button.disabled = true;
    try {
      const result = await api(`auth/${mode}`, { method: "POST", body: JSON.stringify({ email: form.elements.email.value, password: form.elements.password.value }) });
      showErrors(form, {});
      signedIn(result.user);
    } catch (error) {
      showErrors(form, error.errors);
      notify(error.message);
    } finally {
      button.disabled = false;
    }
  });
  document.title = `Sign in · ${config.name}`;
  main.replaceChildren(
    h("h1", { text: mode === "signup" ? "Set up your account" : "Sign in" }),
    h("p", { class: "lead", text: mode === "signup" ? "You are the first person here, so this account will be the owner. You can add others after signing in." : `Sign in to ${config.name}.` }),
    form);
  form.elements.email.focus();
}

function signedIn(who) {
  user = who;
  nav.hidden = false;
  buildNav();
  route();
}

async function signOut() {
  try { await api("auth/logout", { method: "POST" }); } catch { /* signed out either way */ }
  renderSignIn(false);
}

async function renderFiles() {
  const current = currentView();
  const list = h("div", { class: "results", "aria-live": "polite" }, h("p", { class: "loading", text: "Loading…" }));
  const input = h("input", { type: "file", id: "upload", "aria-label": "Choose a file to upload" });
  const load = async () => {
    try {
      const { files, maxBytes } = await api("files");
      if (!current()) return;
      input.dataset.max = String(maxBytes);
      list.replaceChildren(files.length
        ? h("ul", { class: "recent" }, ...files.map((file) => h("li", {},
          h("a", { href: `/api/files/${file.id}`, text: file.name }),
          h("span", { class: "muted", text: `${Math.max(1, Math.round(file.size / 1024))} KB` }),
          h("button", { type: "button", class: "link danger", text: "Delete", "aria-label": `Delete ${file.name}`, onclick: async () => {
            if (!confirm(`Delete ${file.name}?`)) return;
            try { await api(`files/${file.id}`, { method: "DELETE" }); notify("File deleted."); load(); } catch (error) { notify(error.message); }
          } }))))
        : h("p", { class: "empty", text: "No files yet." }));
    } catch (error) {
      if (current() && !error.signedOut) list.replaceChildren(h("p", { class: "error", role: "alert", text: `Could not load files: ${error.message}` }));
    }
  };
  input.addEventListener("change", async () => {
    const file = input.files?.[0];
    if (!file) return;
    if (input.dataset.max && file.size > Number(input.dataset.max)) { notify("That file is too large."); return; }
    try {
      await api("files", { method: "POST", body: file, headers: { "content-type": file.type || "application/octet-stream", "x-file-name": encodeURIComponent(file.name) } });
      notify("File uploaded.");
      input.value = "";
      load();
    } catch (error) { notify(error.message); }
  });
  setPage("Files", h("div", { class: "toolbar" }, input), list);
  await load();
}

function notify(message) {
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(notify.timer);
  notify.timer = setTimeout(() => { toast.hidden = true; }, 3000);
}

function setPage(title, ...content) {
  document.title = `${title} · ${config.name}`;
  main.replaceChildren(h("h1", { text: title }), ...content);
  main.focus({ preventScroll: true });
  const here = location.hash === "" || location.hash === "#/dashboard" && config.home !== "book" ? "#/" : location.hash.split("/").slice(0, 2).join("/");
  for (const link of nav.querySelectorAll("a")) link.toggleAttribute("aria-current", link.getAttribute("href") === here);
}

function inputFor(field, value = "", idPrefix = "f") {
  const id = `${idPrefix}-${field.key}`;
  const common = { id, name: field.key, required: field.required || null };
  let control;
  if (field.type === "textarea") control = h("textarea", { ...common, rows: 3, text: value });
  else if (field.type === "select") control = h("select", common, ...(field.options ?? []).map((option) => h("option", { value: option, selected: option === value || null, text: option })));
  else control = h("input", { ...common, type: field.type === "number" ? "number" : ["email", "tel", "date", "time"].includes(field.type) ? field.type : "text", value, step: field.type === "number" ? "any" : null });
  return h("div", { class: "field" }, h("label", { for: id, text: `${field.label}${field.required ? " *" : ""}` }), control, h("p", { class: "field-error", id: `${id}-error`, hidden: true }));
}

function readForm(form, fields) {
  const data = {};
  for (const field of fields) data[field.key] = form.elements[field.key]?.value ?? "";
  return data;
}

function showErrors(form, errors) {
  for (const node of form.querySelectorAll(".field-error")) { node.hidden = true; node.textContent = ""; }
  for (const [key, message] of Object.entries(errors ?? {})) {
    const node = form.querySelector(`#${CSS.escape(`${form.dataset.prefix}-${key}`)}-error`);
    if (node) { node.textContent = message; node.hidden = false; }
  }
}

function recordForm(entity, { record = null, fields = entity.fields, submitLabel, onSaved, prefix = "f" }) {
  const form = h("form", { class: "card form", novalidate: true, "data-prefix": prefix },
    ...fields.map((field) => inputFor(field, record?.[field.key] ?? "", prefix)),
    h("div", { class: "actions" }, h("button", { type: "submit", text: submitLabel })));
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const button = form.querySelector("button[type=submit]");
    button.disabled = true;
    try {
      const body = JSON.stringify(readForm(form, fields));
      const result = record ? await api(`${entity.slug}/${record.id}`, { method: "PATCH", body }) : await api(entity.slug, { method: "POST", body });
      showErrors(form, {});
      await onSaved(result.record);
    } catch (error) {
      showErrors(form, error.errors);
      notify(error.message);
    } finally {
      button.disabled = false;
    }
  });
  return form;
}

async function renderDashboard() {
  const current = currentView();
  setPage("Dashboard", h("p", { class: "loading", role: "status", text: "Loading…" }));
  try {
    const stats = await api("stats");
    if (!current()) return;
    const cards = config.entities.map((entity) => {
      const stat = stats[entity.slug];
      return h("a", { class: "card stat", href: `#/${entity.slug}` },
        h("span", { class: "stat-label", text: entity.plural }),
        h("strong", { class: "stat-value", text: String(stat.count) }),
        Object.keys(stat.byStatus).length ? h("ul", { class: "breakdown" }, ...Object.entries(stat.byStatus).map(([status, count]) => h("li", {}, h("span", { text: status }), h("span", { text: String(count) })))) : null);
    });
    const recent = await Promise.all(config.entities.map(async (entity) => ({ entity, records: (await api(entity.slug)).records.slice(0, 5) })));
    if (!current()) return;
    setPage("Dashboard",
      h("div", { class: "grid" }, ...cards),
      ...recent.map(({ entity, records }) => h("section", { class: "card" },
        h("h2", { text: `Recent ${entity.plural.toLowerCase()}` }),
        records.length
          ? h("ul", { class: "recent" }, ...records.map((record) => h("li", {}, h("a", { href: `#/${entity.slug}/${record.id}`, text: record[entity.fields[0].key] || `#${record.id}` }), h("span", { class: "muted", text: new Date(record.createdAt).toLocaleDateString() }))))
          : h("p", { class: "empty" }, `No ${entity.plural.toLowerCase()} yet. `, h("a", { href: `#/${entity.slug}/new`, text: `Add the first one` })))));
  } catch (error) {
    if (current()) setPage("Dashboard", h("p", { class: "error", role: "alert", text: `Could not load the dashboard: ${error.message}` }));
  }
}

async function renderList(entity, query = "") {
  const current = currentView();
  const statusField = entity.fields.find((field) => field.type === "select");
  const search = h("input", { type: "search", id: "search", placeholder: `Search ${entity.plural.toLowerCase()}`, "aria-label": `Search ${entity.plural.toLowerCase()}`, value: query });
  const results = h("div", { class: "results", "aria-live": "polite" }, h("p", { class: "loading", text: "Loading…" }));
  setPage(entity.plural,
    h("div", { class: "toolbar" }, search, h("a", { class: "button", href: `#/${entity.slug}/new`, text: `Add ${entity.name.toLowerCase()}` })),
    results);
  // Only the newest search's answer is shown: typing quickly must not let an
  // older, slower response (such as the unfiltered first load) win.
  let latest = 0;
  const load = async () => {
    const request = ++latest;
    const fresh = () => request === latest && current();
    try {
      const { records } = await api(`${entity.slug}?q=${encodeURIComponent(search.value)}`);
      if (!fresh()) return;
      if (!records.length) {
        results.replaceChildren(h("p", { class: "empty", text: search.value ? `No ${entity.plural.toLowerCase()} match "${search.value}".` : `No ${entity.plural.toLowerCase()} yet. Add the first one.` }));
        return;
      }
      const shown = entity.fields.filter((field) => field.type !== "textarea").slice(0, 4);
      results.replaceChildren(h("table", { class: "table" },
        h("thead", {}, h("tr", {}, ...shown.map((field) => h("th", { scope: "col", text: field.label })), h("th", { scope: "col", text: "" }))),
        h("tbody", {}, ...records.map((record) => h("tr", {},
          ...shown.map((field, index) => h("td", { "data-label": field.label }, index === 0 ? h("a", { href: `#/${entity.slug}/${record.id}`, text: record[field.key] || `#${record.id}` }) : field === statusField ? h("span", { class: "pill", text: record[field.key] }) : record[field.key] ?? "")),
          h("td", { class: "row-actions" }, h("button", { type: "button", class: "link danger", text: "Delete", "aria-label": `Delete ${record[entity.fields[0].key] ?? record.id}`, onclick: async () => {
            if (!confirm(`Delete this ${entity.name.toLowerCase()}?`)) return;
            try { await api(`${entity.slug}/${record.id}`, { method: "DELETE" }); notify(`${entity.name} deleted.`); load(); } catch (error) { notify(error.message); }
          } })))))));
    } catch (error) {
      if (fresh()) results.replaceChildren(h("p", { class: "error", role: "alert", text: `Could not load ${entity.plural.toLowerCase()}: ${error.message}` }));
    }
  };
  let timer;
  search.addEventListener("input", () => { clearTimeout(timer); timer = setTimeout(load, 200); });
  await load();
}

async function renderRecord(entity, id) {
  if (id === "new") {
    setPage(`Add ${entity.name.toLowerCase()}`, recordForm(entity, { submitLabel: `Save ${entity.name.toLowerCase()}`, onSaved: (record) => { notify(`${entity.name} saved.`); location.hash = `#/${entity.slug}/${record.id}`; } }));
    return;
  }
  const current = currentView();
  try {
    const { record } = await api(`${entity.slug}/${id}`);
    if (!current()) return;
    setPage(record[entity.fields[0].key] || `${entity.name} #${record.id}`,
      h("p", {}, h("a", { href: `#/${entity.slug}`, text: `← All ${entity.plural.toLowerCase()}` })),
      recordForm(entity, { record, submitLabel: "Save changes", onSaved: () => { notify("Changes saved."); renderRecord(entity, id); } }));
  } catch (error) {
    if (current()) setPage(`${entity.name} not found`, h("p", { class: "error", role: "alert", text: error.message }), h("a", { href: `#/${entity.slug}`, text: `Back to ${entity.plural.toLowerCase()}` }));
  }
}

function renderBooking() {
  const entity = config.entities.find((candidate) => candidate.slug === config.booking.entity);
  const fields = entity.fields.filter((field) => field.key !== "status");
  const done = h("div", { class: "card success", role: "status", hidden: true });
  const form = recordForm(entity, { fields, prefix: "book", submitLabel: "Request booking", onSaved: (record) => {
    form.hidden = true;
    done.hidden = false;
    done.replaceChildren(h("h2", { text: "Thank you!" }), h("p", { text: `Your booking request${record.date ? ` for ${record.date}${record.time ? ` at ${record.time}` : ""}` : ""} was received. We will confirm it shortly.` }), h("button", { type: "button", text: "Make another booking", onclick: () => renderBooking() }));
  } });
  setPage(config.booking.title ?? "Book an appointment", h("p", { class: "lead", text: config.booking.intro ?? "Choose a time that suits you and we will confirm it." }), form, done);
}

function route() {
  view += 1;
  const [, first = "", second] = location.hash.replace(/^#/u, "").split("/");
  nav.classList.remove("open");
  document.getElementById("menu").setAttribute("aria-expanded", "false");
  if (first === "" ) return config.home === "book" && config.booking ? renderBooking() : renderDashboard();
  if (first === "dashboard") return renderDashboard();
  if (first === "book" && config.booking) return renderBooking();
  if (first === "files" && config.files?.enabled !== false) return renderFiles();
  const entity = config.entities.find((candidate) => candidate.slug === first);
  if (!entity) return setPage("Page not found", h("p", {}, "That page does not exist. ", h("a", { href: "#/", text: "Go to the start" })));
  return second ? renderRecord(entity, second) : renderList(entity);
}

async function start() {
  try {
    config = await api("config");
  } catch (error) {
    main.replaceChildren(h("p", { class: "error", role: "alert", text: `The app could not start: ${error.message}` }));
    return;
  }
  document.getElementById("brand").textContent = config.name;
  document.querySelector('meta[name="description"]').setAttribute("content", config.tagline ?? config.name);
  if (config.theme?.accent) document.documentElement.style.setProperty("--accent", config.theme.accent);
  document.getElementById("menu").addEventListener("click", (event) => {
    const open = nav.classList.toggle("open");
    event.currentTarget.setAttribute("aria-expanded", String(open));
  });
  addEventListener("hashchange", () => { if (!config.auth?.required || user || (config.booking && location.hash === "#/book")) route(); });
  if (config.auth?.required) {
    // A booking page stays public: visitors can book without an account.
    const publicBooking = config.booking && (location.hash === "#/book" || (config.home === "book" && location.hash === ""));
    const me = await fetch("/api/auth/me").then(async (response) => ({ ok: response.ok, body: await response.json().catch(() => ({})) })).catch(() => ({ ok: false, body: {} }));
    if (me.ok && me.body.user) return signedIn(me.body.user);
    if (publicBooking) { nav.hidden = true; return renderBooking(); }
    return renderSignIn(Boolean(me.body.signupOpen));
  }
  buildNav();
  route();
}

function buildNav() {
  const links = [];
  if (config.booking) links.push(["#/book", config.booking.navLabel ?? "Book"]);
  links.push([config.home === "book" ? "#/dashboard" : "#/", "Dashboard"]);
  for (const entity of config.entities) links.push([`#/${entity.slug}`, entity.plural]);
  if (config.files?.enabled !== false) links.push(["#/files", "Files"]);
  nav.replaceChildren(...links.map(([href, label]) => h("a", { href, text: label })),
    ...(user ? [h("button", { type: "button", class: "link", text: `Sign out (${user.email})`, onclick: signOut })] : []));
}

start();
